pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address pranker) public {
        // Setup: the current owner must exist and be under our control.
        // We need to obtain the deployer address (the owner of C) and then prank as that owner.
        // Since setUp() deploys C, its owner is this test contract.
        // We can call transferOwnership from this contract directly.
        // But we must also consider the case where the fuzzed owner address is different.
        // Actually, `owner` is a public state variable, initially the contract deployer.
        // The only way `transferOwnership` succeeds is if `msg.sender == owner`.
        // So we must ensure we call as the current owner.
        // However, the owner can be changed over time. To keep it simple and satisfy the rule:
        // We start as owner (this contract). We can prank as ourselves if needed, but we are already the sender.
        // We must allow the fuzzer to supply a newOwner, and we must call transferOwnership as the current owner.
        // We are the current owner, so we can just call `c.transferOwnership(newOwner);`,
        // but we need to ensure it doesn't revert. It will succeed because `msg.sender == owner` is true.
        // However, if the fuzzer makes `newOwner == address(0)`, the assert will pass even for the buggy version.
        // That's fine because the fuzzer will explore non-zero addresses and find a counterexample.
        // But we must also consider that the fuzzer provides `pranker`, but we don't need it here.
        // We can just ignore `pranker`.
        // The simplest correct approach:
        c.transferOwnership(newOwner);
        // The rule: after transferOwnership completes successfully, owner must be newOwner.
        // For the buggy version, owner is set to address(0) regardless, so this will fail for newOwner != address(0).
        assertEq(c.owner(), newOwner);
    }
}

