pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // caller must not accidentally equal the initial owner (msg.sender of setUp is address(this))
        vm.assume(caller != address(this));
        // newOwner can be any address, including address(0) or the current owner

        // Record the owner before the call
        address ownerBefore = c.owner();

        // Attempt transferOwnership as the fuzzed caller
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // The owner after the call
        address ownerAfter = c.owner();

        // Property: If the caller is NOT the current owner, the owner MUST remain unchanged.
        // The reference holds this because onlyOwner reverts for non-owners;
        // the buggy version allows the transfer to succeed for any caller, breaking the invariant.
        assertTrue(
            caller == ownerBefore || ownerAfter == ownerBefore
        );
    }
}

