pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address public initialOwner = address(0x100);

    function setUp() public {
        c = new C();
        c.transferOwnership(initialOwner);
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address oldOwner = c.owner();
        vm.prank(c.owner());
        bool ok = true;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(c.owner(), newOwner, "Owner should be updated on success");
        } else {
            assertEq(c.owner(), oldOwner, "Owner should remain unchanged on failure");
        }
    }
}

